use crate::parser::{
    argument::parse_arguments,
    directive::{is_at_directive, DirectiveList},
    is_at_name,
    parse_error::{
        expected_any_selection, expected_name, expected_type, expected_value,
        expected_variable_definition,
    },
    parse_name,
    r#type::parse_type,
    value::parse_value,
    variable::{is_at_variable, parse_variable},
