+    } else {
+        // name is checked for in `is_at_field`
+        parse_name(p).ok();
+    }
+
+    // arguments are optional
+    parse_arguments(p).ok();
+    DirectiveList.parse_list(p);
+
+    if is_at_selection_set(p) {
+        parse_selection_set(p).ok();
+    }
+    Present(m.complete(p, GRAPHQL_FIELD))
+}
