+#[inline]
+fn parse_variable_definitions(p: &mut GraphqlParser) -> ParsedSyntax {
+    if !p.at(T!['(']) {
+        return Absent;
+    }
+
+    let m = p.start();
+
+    p.bump(T!['(']);
+    VariableDefinitionList.parse_list(p);
+    p.expect(T![')']);
+
+    Present(m.complete(p, GRAPHQL_VARIABLE_DEFINITIONS))
+}
