+#[inline]
+fn is_at_selection(p: &GraphqlParser) -> bool {
+    is_at_field(p) || is_at_fragment(p)
+}
+
+#[inline]
+fn is_at_field(p: &GraphqlParser) -> bool {
+    is_at_name(p)
+}
+
+#[inline]
+fn is_at_fragment(p: &GraphqlParser) -> bool {
+    p.at(DOT3)
+}
